//! Generates member_claims.rs from the engine's own sources: the per-domain
//! member claims the runtime's member routes are built from.
//!
//! The plugin API domain lives in studio, above this crate, so its claims are
//! generated by the root crate's build.rs (`plugin_claims.rs`) and handed to
//! the engine in its Domain at registration (`domains::register`).
//!
//! engine_reads.rs (ENGINE_READS / ENGINE_FIRES) is generated by the root
//! crate's build.rs too: it scans every tree the engine code lives in, and
//! rustudio-core takes the tables at start-up.
//!
//! The source walk is shared with the root build script:
//! build/source_claims.rs.

include!("build/source_claims.rs");

const CLAIMERS: &[(&str, &[&str])] = &[
    ("pages", &["domains/pages"]),
    ("web_social", &["domains/web_social"]),
    ("avatar", &["domains/avatar"]),
    ("data", &["domains/data"]),
    ("anim", &["domains/anim"]),
    ("world", &["domains/world"]),
    ("geometry", &["domains/geometry"]),
    ("gui_input", &["domains/gui_input"]),
    ("media", &["domains/media"]),
    ("services", &["domains/services"]),
    ("players_chat", &["domains/players_chat"]),
    ("assets_cloud", &["domains/assets_cloud"]),
    ("testing", &["domains/testing"]),
    ("ext", &["runtime_ext", "editable"]),
];

fn member_claims() {
    let mut code = String::new();
    let mut pair_code = String::new();
    for (table, root, doc) in [
        ("CLAIMS", "prop_get", "the names its prop_get can answer"),
        ("CALL_CLAIMS", "call", "the method names its call can answer"),
        ("NEWINDEX_CLAIMS", "newindex", "the names its newindex can take"),
    ] {
        code += &format!(
            "/// Per answerer (domains in src/domains/mod.rs order, then runtime_ext):\n\
             /// {doc}, sorted (build.rs member_claims).\n\
             pub static {table}: &[(&str, &[&str])] = &[\n"
        );
        for (name, prefixes) in CLAIMERS {
            let (set, prs) = claim_set(prefixes, root);
            code += &format!("    ({name:?}, &[");
            for w in &set {
                code += &format!("{w:?},");
            }
            code += "]),\n";
            pair_code += &format!("    ({name:?}, &[");
            pair_code += &pair_row(&prs);
            pair_code += "]),\n";
        }
        code += "];\n";
        code += &format!(
            "/// Per answerer: (key, class) literal pairs in the code {table} is made\n\
             /// from, sorted by key; a key found only in pairs is claimed for those\n\
             /// classes only.\n\
             pub static {table}_PAIRS: &[(&str, &[(&str, &str)])] = &[\n"
        );
        code += &std::mem::take(&mut pair_code);
        code += "];\n";
    }
    let out = Path::new(&std::env::var("OUT_DIR").unwrap()).join("member_claims.rs");
    std::fs::write(out, code).unwrap();
    println!("cargo:rerun-if-changed=src");
}


fn main() {
    member_claims();
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=build/source_claims.rs");
}
